
import os
import time
import boto3

# AWS Lambda has a writable /tmp directory
# Set this before importing Matplotlib
os.environ["MPLCONFIGDIR"] = "/tmp/matplotlib"

import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt

from boto3.dynamodb.conditions import Key


# AWS resources
dynamodb = boto3.resource("dynamodb")
s3 = boto3.client("s3")

# Resource names generated by AWS CDK
table = dynamodb.Table(os.environ["TABLE_NAME"])
bucket_name = os.environ["BUCKET_NAME"]


def lambda_handler(event, context):

    # 1. Get the current time in milliseconds
    current_time = int(time.time() * 1000)
    start_time = current_time - 10000

    # 2. Query the last 10 seconds of bucket-size history
    response = table.query(
        KeyConditionExpression=(
            Key("bucket_name").eq(bucket_name) &
            Key("timestamp").between(start_time, current_time)
        )
    )

    items = response["Items"]

    if not items:
        return {
            "statusCode": 200,
            "body": "No recent data to plot"
        }

    # 3. Sort measurements by timestamp
    items.sort(key=lambda item: int(item["timestamp"]))

    raw_timestamps = [
        int(item["timestamp"]) for item in items
    ]

    sizes = [
        int(item["total_size"]) for item in items
    ]

    # Convert timestamps to elapsed seconds
    first_timestamp = raw_timestamps[0]

    elapsed_seconds = [
        (timestamp - first_timestamp) / 1000
        for timestamp in raw_timestamps
    ]

    # 4. Query historical maximum using the GSI
    # No DynamoDB Scan is used
    max_response = table.query(
        IndexName="GlobalSizeIndex",
        KeyConditionExpression=(
            Key("global_key").eq("ALL_BUCKETS")
        ),
        ScanIndexForward=False,
        Limit=1
    )

    if max_response["Items"]:
        max_size = int(
            max_response["Items"][0]["total_size"]
        )
    else:
        max_size = 0

    # 5. Create a single zoomed-in graph
    fig, ax = plt.subplots(figsize=(10, 5))

    ax.plot(
        elapsed_seconds,
        sizes,
        marker="o",
        markersize=7,
        linewidth=2,
        label="Bucket Size"
    )

    # Add labels above each measurement
    for x, y in zip(elapsed_seconds, sizes):
        ax.annotate(
            f"{y} bytes",
            (x, y),
            textcoords="offset points",
            xytext=(0, 10),
            ha="center"
        )

    # Keep the Y-axis focused on the recent measurements
    ax.set_ylim(
        bottom=0,
        top=max(max(sizes) * 1.3 + 5, 10)
    )

    # Labels and formatting
    ax.set_title("S3 Bucket Size History")
    ax.set_xlabel("Elapsed Time (seconds)")
    ax.set_ylabel("Bucket Size (bytes)")
    ax.grid(True, linestyle="--", alpha=0.4)
    ax.legend(loc="upper left")

    # Show historical maximum without affecting graph scale
    ax.text(
        0.98,
        0.95,
        f"Historical Max: {max_size:,} bytes",
        transform=ax.transAxes,
        ha="right",
        va="top",
        fontsize=10,
        bbox=dict(
            facecolor="white",
            edgecolor="gray",
            alpha=0.9
        )
    )

    fig.tight_layout()

    # 6. Save the graph to Lambda temporary storage
    file_path = "/tmp/plot.png"

    fig.savefig(
        file_path,
        dpi=150,
        bbox_inches="tight"
    )

    plt.close(fig)

    # 7. Upload the plot to S3
    s3.upload_file(
        file_path,
        bucket_name,
        "plot.png",
        ExtraArgs={"ContentType": "image/png"}
    )

    print(f"Plot uploaded to S3: {bucket_name}/plot.png")
    print(f"Recent measurements: {sizes}")
    print(f"Historical maximum: {max_size} bytes")

    return {
        "statusCode": 200,
        "body": "Plot created successfully"
    }
